Repair the complete CommonJS source below and return a corrected complete source file exporting exactly `{ tracePlan }`.

`tracePlan(nodes)` accepts an array representing an ordered forest. Every node must be a plain object shaped `{ label, children }`, where `label` is a non-empty string and `children` is an array of nodes. It returns the labels in depth-first pre-order: record a node's label before visiting its children from left to right. An empty forest returns an empty array. Shared node objects are allowed and are visited once per occurrence; cyclic references are malformed and throw `RangeError`. Sparse arrays and malformed nodes throw `TypeError`.

The function must not mutate the forest, nodes, or child arrays. Its returned array must be independent of all inputs.

Known-bad source:

```javascript
'use strict';

function tracePlan(nodes) {
  if (!Array.isArray(nodes)) throw new TypeError('nodes must be an array');
  const output = [];
  const ancestors = new Set();

  function visitList(list) {
    for (let index = 0; index < list.length; index++) {
      if (!Object.prototype.hasOwnProperty.call(list, index)) throw new TypeError('sparse arrays are unsupported');
      visit(list[index]);
    }
  }

  function visit(node) {
    if (node === null || typeof node !== 'object' || Array.isArray(node)) throw new TypeError('invalid node');
    const prototype = Object.getPrototypeOf(node);
    if (prototype !== Object.prototype && prototype !== null) throw new TypeError('invalid node');
    if (typeof node.label !== 'string' || node.label.length === 0 || !Array.isArray(node.children)) {
      throw new TypeError('invalid node');
    }
    if (ancestors.has(node)) throw new RangeError('cycle detected');
    ancestors.add(node);
    visitList(node.children);
    output.push(node.label);
    ancestors.delete(node);
  }

  visitList(nodes);
  return output;
}

module.exports = { tracePlan };
```

