'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['tracePlan']);
const { tracePlan } = api;

assert.deepStrictEqual(tracePlan([]), []);
const forest = [
  {
    label: 'A',
    children: [
      { label: 'B', children: [] },
      { label: 'C', children: [{ label: 'D', children: [] }] }
    ]
  },
  { label: 'E', children: [] }
];
assert.deepStrictEqual(tracePlan(forest), ['A', 'B', 'C', 'D', 'E']);
assert.deepStrictEqual(forest[0].children.map((node) => node.label), ['B', 'C']);

const shared = { label: 'shared', children: [] };
assert.deepStrictEqual(tracePlan([
  { label: 'left', children: [shared] },
  { label: 'right', children: [shared] }
]), ['left', 'shared', 'right', 'shared']);

for (const value of [null, {}, 'forest']) assert.throws(() => tracePlan(value), TypeError);
const sparseForest = new Array(1);
assert.throws(() => tracePlan(sparseForest), TypeError);
const sparseChildren = new Array(1);
assert.throws(() => tracePlan([{ label: 'x', children: sparseChildren }]), TypeError);

const malformedNodes = [
  null, [], {}, { label: '', children: [] }, { label: 3, children: [] },
  { label: 'x', children: null }, new Date()
];
for (const node of malformedNodes) assert.throws(() => tracePlan([node]), TypeError);

const self = { label: 'self', children: [] };
self.children.push(self);
assert.throws(() => tracePlan([self]), RangeError);
const first = { label: 'first', children: [] };
const second = { label: 'second', children: [first] };
first.children.push(second);
assert.throws(() => tracePlan([first]), RangeError);

const input = [{ label: 'stable', children: [] }];
const output = tracePlan(input);
output.push('mutation');
assert.deepStrictEqual(input, [{ label: 'stable', children: [] }]);
assert.deepStrictEqual(tracePlan(input), ['stable']);

